LuaScript:
-- Через 3 секунды после загрузки фиксируем карту, планшеты и листы правил, чтобы их не сдвинуть случайно.
local LOCK = { "a90351", "1e2d16", "7df90d", "0382a4", "02561e", "512ddc", "9b0084", "a0daa9", "e4ba98", "f28fc3", "a85910", "f20838", "163137", "8212cd", "e29de4", "d93b31" }
function onLoad()
  Wait.time(function()
    for _, g in ipairs(LOCK) do
      local o = getObjectFromGUID(g)
      if o then o.setLock(true) end
    end
  end, 3)
end
